import { createClient } from '@supabase/supabase-js'
import type { Database } from './database.types'
import { env } from './env'

/**
 * The one Supabase client for the app, typed from the live schema
 * (database.types.ts is generated by `supabase gen types`, never edited by hand).
 *
 * Guests and admins never read tables through it: RLS denies every table to
 * them, and all data comes from `supabase.rpc(...)` calls to SQL functions.
 * The table types it carries describe the schema, not what a client may touch.
 */
export const supabase = createClient<Database>(env.supabaseUrl, env.supabaseAnonKey)
